if(network.membershipVersion != undefined && network.membershipVersion !== 1) return {error:"invalid membership version"};
membershipVersion = network.membershipVersion == 1 ? 1 : 0;
if(membershipVersion == 1 && (initialPlayers != 1 || !personalProgression || mode != "Coop"))
   return {error:"membership events require an initially solo personal Cooperative world"};

if(leave !== undefined)
{
   if(!this.BH_ValidLeave(leave,join,p2Mask)) return this.BH_Fail("invalid player leave");
}

if(b.membershipVersion != 1) this.BH_ReplayFinish();
if(b.membershipVersion == 1)
{
   if(!CMain.BH_Integer(b.guestGeneration,0,2147483646)) throw new Error("guest generation exhausted");
   b.guestGeneration++;
}

}

function BH_ValidLeave(leave, join, p2Mask)
{
   var b = this.mBH;
   if(b.membershipVersion !== 1 || b.initialPlayers !== 1 || !b.personalProgression || b.mode != "Coop"
      || b.playerCount !== 2 || join != undefined || p2Mask !== 0 || typeof leave != "object"
      || leave == null || leave instanceof Array || leave.slot !== 2) return false;
   var count = 0;
   for(var key in leave) { if(key != "slot") return false; count++; }
   return count == 1;
}

function BH_LeavePlayer()
{
   var b = this.mBH;
   var w = this.mcWorld;
   var c = w.mThing_Collection;
   if(!b.stepping || b.membershipVersion !== 1 || b.playerCount !== 2 || c == undefined
      || c.mThings == undefined || c.mPlayerThings == undefined || c.mDeleteThings == undefined)
      throw new Error("player leave outside membership frame");
   var guest;
   var host;
   var count = 0;
   for(var key in c.mPlayerThings)
   {
      var player = c.mPlayerThings[key];
      count++;
      if(player.mPlayerIndex === 0 && host == undefined) host = player;
      else if(player.mPlayerIndex === 1 && guest == undefined) guest = player;
      else throw new Error("ambiguous player roster");
   }
   if(count != 2 || host == undefined || guest == undefined || guest.sUniqueID == undefined
      || host.sUniqueID == undefined || host._CLASSID_ != "CThing_Creature_Player" || guest._CLASSID_ != "CThing_Creature_Player"
      || c.mThings[host.sUniqueID] !== host || c.mPlayerThings[host.sUniqueID] !== host
      || c.mDeleteThings[host.sUniqueID] != undefined
      || c.mThings[guest.sUniqueID] !== guest || c.mPlayerThings[guest.sUniqueID] !== guest
      || c.mDeleteThings[guest.sUniqueID] != undefined || w.mUpgrades.mTotalPlayerCount != 2
      || c.mThingCounters.CThing_Creature_Player != 2
      || w.mBHPersonalProgress == undefined || w.mBHPersonalProgress[1] == undefined
      || w.mBHPersonalProgress[1].upgrades.mWorld.mThing_Collection.mPlayerThings.owner !== guest)
      throw new Error("unsafe guest removal state");
   if(typeof host.mStateID != "string" || typeof host[host.mStateID] != "function"
      || typeof guest.mStateID != "string" || typeof guest[guest.mStateID] != "function"
      || typeof host.mLife != "number" || !isFinite(host.mLife)
      || typeof guest.mLife != "number" || !isFinite(guest.mLife))
      throw new Error("unsafe player lifecycle state");
   // LogKill decrements the live count on entry to Dying, not on the
   // preceding lethal hit. Dead and Respawn retain that decrement until
   // the original respawn succeeds. Validate both players against it.
   var guestCounted = guest.mStateID != "State_Dying" && guest.mStateID != "State_Dead" && guest.mStateID != "State_Respawn";
   var hostCounted = host.mStateID != "State_Dying" && host.mStateID != "State_Dead" && host.mStateID != "State_Respawn";
   if(w.mUpgrades.mPlayerCount !== (guestCounted ? 1 : 0) + (hostCounted ? 1 : 0))
      throw new Error("unsafe player count");
   var cell = guest.mNewCell;
   if(cell !== undefined && (cell == null || !CMain.BH_Integer(cell.mCollide,0,2147483647)
      || guest.mNewCell_Flags !== World.Map.CMap_Cell.mCollide_Player || typeof guest.ClearCollideCell != "function"))
      throw new Error("unsafe guest collision cell");
   // ClearCollideCell uses the original bit-mask operation even when a
   // second player occupies the same cell; it is not a reference count.
   // Queue disposal once; DeleteThing_Player would Dispose twice.
   CMain.mInput.BH_ResetGuestKeys();
   if(cell !== undefined) guest.ClearCollideCell();
   delete guest.Process;
   c.DeleteThing(guest);
   delete c.mPlayerThings[guest.sUniqueID];
   if(guestCounted) w.mUpgrades.mPlayerCount--;
   w.mUpgrades.mTotalPlayerCount--;
   w.mBHPersonalProgress[1] = undefined;
   World.CWorld.m2Player = false;
   b.playerCount = 1;
